SourceCode.Declaration:
/// <summary>
/// One active claim on a counting journal, returned inside HSMobileOpsJournalSummaryRow.Claims
/// so the list screen can show who holds which part of a journal. Display data only - the claim
/// rules themselves (TTL, one claim per range, who may take over) live in X++, not on the device.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountClaimRow
{
    str         claimedBy;
    str         deviceId;
    str         rangeId;
    str         locationFrom;
    str         locationTo;
    utcdatetime expiresUtc;

}

Method.Source:
[DataMemberAttribute('ClaimedBy')]
public str parmClaimedBy(str _value = claimedBy)
{
    claimedBy = _value;
    return claimedBy;
}

[DataMemberAttribute('DeviceId')]
public str parmDeviceId(str _value = deviceId)
{
    deviceId = _value;
    return deviceId;
}

[DataMemberAttribute('RangeId')]
public str parmRangeId(str _value = rangeId)
{
    rangeId = _value;
    return rangeId;
}

[DataMemberAttribute('LocationFrom')]
public str parmLocationFrom(str _value = locationFrom)
{
    locationFrom = _value;
    return locationFrom;
}

[DataMemberAttribute('LocationTo')]
public str parmLocationTo(str _value = locationTo)
{
    locationTo = _value;
    return locationTo;
}

[DataMemberAttribute('ExpiresUtc')]
public utcdatetime parmExpiresUtc(utcdatetime _value = expiresUtc)
{
    expiresUtc = _value;
    return expiresUtc;
}
